const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

function buildCommand() {
  const __args = [['grok'], 'AI', 'Chat with xAI\'s Grok', async ({ sock, from, msg, args }) => {
  const prompt = args.join(' ');
  if (!prompt) return sock.sendMessage(from, { text: 'Usage: .grok <your question>' }, { quoted: msg });
  const key = process.env.XAI_API_KEY;
  if (!key) return sock.sendMessage(from, { text: '⚠️ Grok not set up yet — add XAI_API_KEY in .env. Get one at console.x.ai (check their current pricing, this one isn\'t reliably free).' }, { quoted: msg });
  try {
    const res = await fetch('https://api.x.ai/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${key}` },
      body: JSON.stringify({ model: 'grok-beta', messages: [{ role: 'user', content: prompt }] })
    });
    const data = await res.json();
    const reply = data.choices?.[0]?.message?.content || 'No response.';
    await sock.sendMessage(from, { text: reply }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Grok service unavailable right now.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
